// Extract the current topic and clean up input fields
const item = $input.first().json;
const topic = String(item.Topic || item.topic || '').trim();

if (!topic) {
  throw new Error("Topic is empty or invalid.");
}

return [{
  json: {
    topic: topic,
    originalStatus: item.Status || 'New',
    rowNumber: item.row_number || null,
    fetchedAt: new Date().toISOString()
  }
}];

// 1. Extract raw output from the AI Agent node
let rawOutput = "";
if ($input.first() && $input.first().json && $input.first().json.output) {
  rawOutput = $input.first().json.output;
} else if (typeof item !== 'undefined' && item.json && item.json.output) {
  rawOutput = item.json.output;
}

if (!rawOutput) {
  throw new Error("No output received from Gemini AI node.");
}

// 2. Clean markdown code fences if present
let cleanJson = String(rawOutput)
  .replace(/^\s*```(?:json)?/i, '')
  .replace(/```\s*$/, '')
  .trim();

const firstBrace = cleanJson.indexOf('{');
const lastBrace = cleanJson.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
  cleanJson = cleanJson.slice(firstBrace, lastBrace + 1);
}

let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  throw new Error("Failed to parse Gemini output as JSON: " + e.message + " | Raw: " + rawOutput.slice(0, 200));
}

// 3. Category Mapping for EveryGyan database
const categoryLookup = {
  'tech': { id: 'e0563385-fdbf-4657-81ec-051799f8f16b', name: 'Tech', slug: 'tech' },
  'travel': { id: 'b5a4c3d0-f6e9-46b3-80f8-36b701f8a397', name: 'Travel', slug: 'travel' },
  'learning': { id: '4408e73f-bef5-462f-a954-93b0b6198ad2', name: 'Learning', slug: 'learning' },
  'health': { id: '19f93cb4-b6fe-48ed-be2d-e9ab08d66bbd', name: 'Health & Wellness', slug: 'health' },
  'news': { id: '49274f31-92f7-4b94-ac44-9a1399a3bebe', name: 'Latest News', slug: 'latest-news' }
};

const catKey = (parsed.category || 'tech').toLowerCase();
let matchedCat = categoryLookup['tech'];
for (const [k, v] of Object.entries(categoryLookup)) {
  if (catKey.includes(k) || k.includes(catKey)) {
    matchedCat = v;
    break;
  }
}

// 4. Retrieve original topic context
const originalTopic = $("Prepare Topic Context").first().json.topic;

// 5. Generate Slug
const slugBase = (parsed.slug || parsed.title || originalTopic)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 70);

const uniqueSlug = slugBase + '-' + Math.random().toString(36).substring(2, 6);

// 6. Build Article Record matching public.articles in Supabase
const articleRecord = {
  title: String(parsed.title || originalTopic).trim(),
  slug: uniqueSlug,
  excerpt: String(parsed.excerpt || (parsed.content || '').slice(0, 150) + '...').trim(),
  content: String(parsed.content || '').trim(),
  category: matchedCat.name,
  category_slug: matchedCat.slug,
  category_id: matchedCat.id,
  author_id: "a5d5fa9e-8101-45b6-9e1f-2be5f2c499f7",
  tags: Array.isArray(parsed.tags) ? parsed.tags : [originalTopic, matchedCat.name, "EveryGyan"],
  read_time: parsed.read_time || "3 min read",
  cover_image: parsed.cover_image || 'https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?auto=format&fit=crop&w=1200&q=80',
  cover_caption: parsed.cover_caption || parsed.title || originalTopic,
  status: "draft",
  published_at: null,
  is_lead_story: false,
  is_featured: false,
  views_count: 0,
  seo_title: parsed.seo_title || (parsed.title + " | EveryGyan"),
  seo_description: parsed.seo_description || parsed.excerpt || "",
  table_of_contents: parsed.table_of_contents || [
    { id: "overview", level: 2, title: "Overview" },
    { id: "key-takeaways", level: 3, title: "Key Takeaways" },
    { id: "conclusion", level: 2, title: "Conclusion" }
  ],
  references: parsed.references || [
    { title: "EveryGyan", url: "https://everygyan.com" }
  ],
  template_type: "standard",
  template_data: {},
  is_carousel: false
};

return [{
  json: {
    originalTopic: originalTopic,
    article: articleRecord
  }
}];

// Prepare beautifully formatted HTML content for the Google Doc
const articleData = $("Format & Validate EveryGyan Article").first().json.article;
const originalTopic = $("Prepare Topic Context").first().json.topic;

function mdToHtml(md) {
  if (!md) return "";
  let html = md
    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
    .replace(/^# (.*$)/gim, '<h1>$1</h1>')
    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
    .replace(/^\s*[-*]\s+(.*$)/gim, '<li>$1</li>')
    .replace(/^\>\s+(.*$)/gim, '<blockquote style="border-left: 3px solid #1a73e8; margin: 1em 0; padding-left: 1em; color: #555;">$1</blockquote>')
    .replace(/\n\s*\n/gim, '</p><p>');

  html = html.replace(/(<li>[\s\S]*?<\/li>)/gim, '<ul style="padding-left: 20px;">$1</ul>');
  return '<p>' + html + '</p>';
}

const bodyHtml = mdToHtml(articleData.content);

const fullHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #202124;">
  <h1 style="color: #1a73e8; margin-bottom: 6px;">${articleData.title}</h1>
  <p style="color: #5f6368; font-size: 13px; margin-top: 0;">
    <strong>Topic:</strong> ${originalTopic} &nbsp;|&nbsp;
    <strong>Category:</strong> ${articleData.category} &nbsp;|&nbsp;
    <strong>Workflow State:</strong> Draft (Work in Progress) &nbsp;|&nbsp;
    <strong>Read Time:</strong> ${articleData.read_time}
  </p>
  <hr style="border: 0; border-top: 1px solid #dadce0; margin: 16px 0;" />
  <div style="background-color: #f8f9fa; border-left: 4px solid #1a73e8; padding: 12px 16px; margin-bottom: 20px;">
    <strong style="color: #202124;">Summary / Excerpt:</strong>
    <p style="margin: 4px 0 0 0; color: #3c4043;">${articleData.excerpt}</p>
  </div>
  <hr style="border: 0; border-top: 1px solid #dadce0; margin: 16px 0;" />
  ${bodyHtml}
  <hr style="border: 0; border-top: 1px solid #dadce0; margin: 24px 0;" />
  <h3 style="color: #1a73e8;">Search Engine & CMS Metadata</h3>
  <ul>
    <li><strong>SEO Title:</strong> ${articleData.seo_title}</li>
    <li><strong>SEO Meta Description:</strong> ${articleData.seo_description}</li>
    <li><strong>Article Tags:</strong> ${articleData.tags.join(', ')}</li>
    <li><strong>Target Slug:</strong> /post/${articleData.slug}</li>
  </ul>
</body>
</html>`;

return [{
  json: {
    docTitle: articleData.title + " (Draft)",
    htmlContent: fullHtml,
    originalTopic: originalTopic
  }
}];
